//! LiteLLM HTTP client for the in-CLI agent runtime (v0.1 Wednesday).
//!
//! LiteLLM exposes an OpenAI-compatible Chat Completions API at
//! `POST /v1/chat/completions`. The `model` field in the request
//! is the *alias* declared in the user's `.ais` source (e.g. `fast`)
//! — LiteLLM's `model_list` config (generated by `aislang-compose`
//! in week 5) translates that alias to a concrete provider/model
//! pair, applies fallbacks per `router_settings.fallbacks`, and
//! handles auth from env vars (`os.environ/ANTHROPIC_API_KEY` etc.).
//!
//! v0.1 is non-streaming (Decision 3): one full response per turn.
//! v0.1 also doesn't pass `tools` (Thursday wires that). The
//! `LiteLlmClient` API is intentionally small — Wednesday gets the
//! `send_chat` round-trip working; Thursday adds `send_chat_with_tools`
//! as a new method on the same struct.

use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::time::Duration;
use thiserror::Error;

// ============================================================================
// Wire types — OpenAI-compatible Chat Completions API
// ============================================================================

/// Top-level chat-completion request body.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ChatRequest {
    /// Model alias from the `.ais` `model` block (e.g. `"fast"`).
    /// LiteLLM resolves this through its `model_list` config.
    pub model:    String,
    pub messages: Vec<ChatMessage>,
    /// Non-streaming for v0.1 (Decision 3). Always `false` here; the
    /// field is sent explicitly to be unambiguous about it (some
    /// proxies default to streaming).
    pub stream:   bool,
    /// Tool catalog (week-6 Thu). When `None`, LiteLLM gets a plain
    /// chat request — same wire shape as Wed. When `Some(non-empty)`,
    /// the model is told what tools it can call; on its turn it can
    /// emit `tool_calls` on the assistant message.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tools:    Option<Vec<Tool>>,
    /// Per-request timeout hint surfaced to LiteLLM. Optional in the
    /// wire format — only set when the user pins it via the .ais
    /// `model.latency_p95` (v0.2).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub timeout:  Option<u64>,
}

/// One message in a chat exchange.
///
/// `content` and `tool_calls` and `tool_call_id` are all optional —
/// which combination is valid depends on the `role`:
///   - **system**, **user**: require `content` (string).
///   - **assistant**: requires `content` OR `tool_calls` (or both).
///     When the model wants to invoke tools, it emits `tool_calls`
///     with no `content`; when it's giving a final answer, it emits
///     `content` with no `tool_calls`.
///   - **tool**: requires `content` (the tool's textual output) AND
///     `tool_call_id` (matching the assistant's `tool_calls[i].id`
///     so LiteLLM can pair them).
///
/// v0.1's chat loop manages the invariants. The struct itself is
/// permissive — invalid combinations are rejected by LiteLLM, not
/// here.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ChatMessage {
    pub role: Role,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content: Option<String>,
    /// Tool invocations emitted by the assistant when it wants the
    /// runtime to dispatch one or more MCP calls. Populated on
    /// assistant messages only.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_calls: Option<Vec<ToolCall>>,
    /// Pairing key on `role=tool` messages — must match a
    /// `tool_calls[i].id` from the preceding assistant message.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_call_id: Option<String>,
}

impl ChatMessage {
    /// Helper: build a plain `{role, content}` message (system/user/
    /// tool-without-id). Most v0.1 call sites use this shape.
    pub fn text(role: Role, content: impl Into<String>) -> Self {
        Self {
            role,
            content: Some(content.into()),
            tool_calls: None,
            tool_call_id: None,
        }
    }

    /// Helper: build a tool-response message that pairs with a
    /// specific assistant `tool_calls[i].id`.
    pub fn tool_response(call_id: impl Into<String>, content: impl Into<String>) -> Self {
        Self {
            role: Role::Tool,
            content: Some(content.into()),
            tool_calls: None,
            tool_call_id: Some(call_id.into()),
        }
    }
}

// -- Tool wire types (OpenAI-compatible) ---------------------------------- //

/// One tool exposed to the model in the request's `tools` array.
/// `type` is always `"function"` for v0.1 (OpenAI also has
/// `code_interpreter` / `file_search` etc., but those don't apply
/// to MCP-routed tools).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Tool {
    #[serde(rename = "type")]
    pub kind: String,
    pub function: ToolFunction,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ToolFunction {
    pub name: String,
    pub description: String,
    /// JSON Schema describing the tool's input. Passed verbatim from
    /// the MCP server's `tools/list` response.
    pub parameters: serde_json::Value,
}

/// One tool invocation in an assistant message's `tool_calls` array.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ToolCall {
    /// Server-generated ID used to pair this call with its
    /// `role=tool` response message.
    pub id: String,
    #[serde(rename = "type")]
    pub kind: String,
    pub function: FunctionCall,
}

/// Quirk of the OpenAI spec: `function.arguments` is a JSON-encoded
/// **string** containing a JSON object, NOT a JSON object directly.
/// Callers must `serde_json::from_str(&call.function.arguments)` to
/// get the parsed argument map. Documented here so callers don't
/// have to re-discover it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FunctionCall {
    pub name: String,
    pub arguments: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Role {
    System,
    User,
    Assistant,
    /// Tool-response messages (used by the tool-use loop on Thursday).
    /// Carried through the v0.1 Wed type now so the wire format
    /// is forward-compatible.
    Tool,
}

/// What LiteLLM returns for a non-streaming chat completion. Mirrors
/// the OpenAI schema, with optional fields skipped — we only care
/// about `choices[0].message.content` for v0.1 Wed.
#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct ChatResponse {
    #[serde(default)] pub id:      Option<String>,
    #[serde(default)] pub model:   Option<String>,
    pub choices:                   Vec<ChatChoice>,
    /// Token usage — populated by LiteLLM when the upstream provider
    /// returns it. The budget counter in week 7 will key on this.
    #[serde(default)] pub usage:   Option<UsageStats>,
}

#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct ChatChoice {
    #[serde(default)] pub index:         u32,
    pub message:                          ChatMessage,
    #[serde(default)] pub finish_reason:  Option<String>,
}

#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct UsageStats {
    #[serde(default)] pub prompt_tokens:     u32,
    #[serde(default)] pub completion_tokens: u32,
    #[serde(default)] pub total_tokens:      u32,
}

// ============================================================================
// Errors
// ============================================================================

#[derive(Debug, Error)]
pub enum LiteLlmError {
    #[error("HTTP request to LiteLLM at `{url}` failed: {cause}")]
    Transport { url: String, cause: String },

    #[error("LiteLLM returned HTTP {status} from `{url}`: {body}")]
    BadStatus { url: String, status: u16, body: String },

    #[error("could not parse LiteLLM response from `{url}`: {cause}\n--- body ---\n{body}")]
    BadResponse { url: String, cause: String, body: String },

    #[error("LiteLLM returned no choices (chat response had empty choices[])")]
    EmptyChoices,
}

// ============================================================================
// `LiteLlmClient`
// ============================================================================

/// Thin HTTP client for LiteLLM's Chat Completions endpoint.
///
/// Pin the timeout at construction (v0.1 = 30s). One client instance
/// per chat session is fine — reqwest re-uses connections internally.
pub struct LiteLlmClient {
    http:     Client,
    base_url: String,
}

impl LiteLlmClient {
    /// Default LiteLLM port exposed by the compose stack (matches
    /// `litellm` service port mapping in `aislang-compose`).
    /// Default LiteLLM URL. Uses **`127.0.0.1`** explicitly (not
    /// `localhost`) to dodge a real-world bite: on Linux hosts where
    /// `/etc/hosts` maps `localhost` to both `127.0.0.1` and `::1`,
    /// reqwest's name resolution may try IPv6 first and hit Docker's
    /// flaky `[::]:4000->4000/tcp` mapping (it's listed but TCP
    /// connect frequently RSTs depending on kernel/userspace-proxy
    /// config). `127.0.0.1` is unambiguous IPv4 → straight to the
    /// `0.0.0.0:4000` published port → works everywhere.
    ///
    /// Observed week-7 Thu: with `localhost`, `curl http://localhost:4000/health/liveness`
    /// works (curl tries v4 after v6 fails) but reqwest's request
    /// surfaces "error sending request for url" because it commits
    /// to the first-resolved address. Pinning v4 sidesteps it.
    pub const DEFAULT_URL: &'static str = "http://127.0.0.1:4000";

    /// 30 seconds — the same default the v0.2 OTel spans will use.
    /// Long enough for slow models (Opus, GPT-4o), short enough that
    /// a broken proxy doesn't hang the chat loop forever.
    pub const DEFAULT_TIMEOUT_SECS: u64 = 30;

    /// Build a client pointing at the given LiteLLM base URL.
    /// `base_url` must NOT include the `/v1/...` path — that's
    /// appended per-call.
    pub fn new(base_url: impl Into<String>) -> Result<Self, LiteLlmError> {
        let base_url = base_url.into();
        let http = Client::builder()
            .timeout(Duration::from_secs(Self::DEFAULT_TIMEOUT_SECS))
            .build()
            .map_err(|e| LiteLlmError::Transport {
                url:   base_url.clone(),
                cause: e.to_string(),
            })?;
        Ok(Self { http, base_url })
    }

    /// `Self::new(DEFAULT_URL)`. Convenience for the most common case.
    pub fn default_local() -> Result<Self, LiteLlmError> {
        Self::new(Self::DEFAULT_URL)
    }

    /// POST a non-streaming chat completion. Returns the first
    /// choice's assistant message content as a plain `String`.
    ///
    /// For requests with no `tools` array (Wed-style simple turns),
    /// this is the most ergonomic API. For tool-use turns the loop
    /// needs access to `tool_calls`; use [`send_chat_full`] instead.
    pub async fn send_chat(&self, req: &ChatRequest) -> Result<String, LiteLlmError> {
        let response = self.send_chat_full(req).await?;
        let first = response.choices.into_iter().next()
            .ok_or(LiteLlmError::EmptyChoices)?;
        Ok(first.message.content.unwrap_or_default())
    }

    /// POST a non-streaming chat completion and return the full
    /// parsed `ChatResponse`. Required by the tool-use loop (Thu)
    /// because it needs `choices[0].message.tool_calls`, not just
    /// the textual content.
    pub async fn send_chat_full(&self, req: &ChatRequest) -> Result<ChatResponse, LiteLlmError> {
        let url = format!("{}/v1/chat/completions", self.base_url);
        let response = self.http.post(&url)
            .json(req)
            .send().await
            .map_err(|e| LiteLlmError::Transport {
                url:   url.clone(),
                cause: e.to_string(),
            })?;
        let status = response.status();
        let body = response.text().await.unwrap_or_default();
        if !status.is_success() {
            return Err(LiteLlmError::BadStatus {
                url,
                status: status.as_u16(),
                body,
            });
        }
        let parsed: ChatResponse = serde_json::from_str(&body)
            .map_err(|e| LiteLlmError::BadResponse {
                url:   url.clone(),
                cause: e.to_string(),
                body:  body.clone(),
            })?;
        Ok(parsed)
    }
}

// ============================================================================
// Helper: build a one-turn ChatRequest (system + user) — used by both
// the session module and tests that pin the wire shape.
// ============================================================================

/// Build a request with one system message + one user message + no
/// tools. Stream is hard-set to `false` per Decision 3. Used by
/// callers that aren't running a tool-use loop (e.g. the prompt
/// hashing harness, tests).
pub fn one_turn_request(model: &str, system: &str, user: &str) -> ChatRequest {
    ChatRequest {
        model:    model.to_string(),
        messages: vec![
            ChatMessage::text(Role::System, system),
            ChatMessage::text(Role::User,   user),
        ],
        stream:   false,
        tools:    None,
        timeout:  None,
    }
}

// ============================================================================
// Tests
// ============================================================================

#[cfg(test)]
mod tests {
    use super::*;

    // ---- wire-type JSON contracts ----

    #[test] fn chat_request_serializes_with_lowercase_role() {
        let req = one_turn_request("fast", "you are helpful", "hi");
        let s = serde_json::to_string(&req).unwrap();
        // Roles must be lowercase per OpenAI spec.
        assert!(s.contains("\"role\":\"system\""), "system role lowercased: {s}");
        assert!(s.contains("\"role\":\"user\""),   "user role lowercased: {s}");
        // Stream explicitly false (not omitted).
        assert!(s.contains("\"stream\":false"), "stream=false explicit: {s}");
        // Model alias passes through verbatim.
        assert!(s.contains("\"model\":\"fast\""));
    }

    #[test] fn chat_request_omits_timeout_when_none() {
        let req = one_turn_request("fast", "sys", "user");
        let s = serde_json::to_string(&req).unwrap();
        // The `timeout` field is skip_serializing_if=None — omitted.
        assert!(!s.contains("timeout"),
            "timeout must be omitted when None; got: {s}");
    }

    #[test] fn chat_response_parses_minimal_shape() {
        // What LiteLLM returns for a successful one-turn completion.
        let body = r#"{
            "id": "chatcmpl-abc",
            "model": "ollama/llama3.1:8b",
            "choices": [
                {
                    "index": 0,
                    "message": {"role": "assistant", "content": "hello!"},
                    "finish_reason": "stop"
                }
            ],
            "usage": {"prompt_tokens": 5, "completion_tokens": 2, "total_tokens": 7}
        }"#;
        let parsed: ChatResponse = serde_json::from_str(body).unwrap();
        assert_eq!(parsed.choices.len(), 1);
        assert_eq!(parsed.choices[0].message.role, Role::Assistant);
        assert_eq!(parsed.choices[0].message.content.as_deref(), Some("hello!"));
        assert_eq!(parsed.usage.as_ref().unwrap().total_tokens, 7);
    }

    #[test] fn chat_response_parses_without_optional_fields() {
        // Minimal valid response: just choices[0].message.content.
        // Some upstream providers don't fill in usage / finish_reason.
        let body = r#"{"choices": [{"message": {"role": "assistant", "content": "ok"}}]}"#;
        let parsed: ChatResponse = serde_json::from_str(body).unwrap();
        assert_eq!(parsed.choices[0].message.content.as_deref(), Some("ok"));
        assert!(parsed.usage.is_none());
        assert!(parsed.choices[0].finish_reason.is_none());
    }

    #[test] fn role_tool_round_trips() {
        let m = ChatMessage::tool_response("call_abc", "tool output");
        let s = serde_json::to_string(&m).unwrap();
        assert!(s.contains("\"role\":\"tool\""), "got: {s}");
        assert!(s.contains("\"tool_call_id\":\"call_abc\""),
            "tool messages must carry tool_call_id; got: {s}");
        let back: ChatMessage = serde_json::from_str(&s).unwrap();
        assert_eq!(back.role, Role::Tool);
        assert_eq!(back.tool_call_id.as_deref(), Some("call_abc"));
        assert_eq!(back.content.as_deref(), Some("tool output"));
    }

    // ---- LiteLlmClient construction ----

    #[test] fn client_new_with_explicit_url() {
        let c = LiteLlmClient::new("http://litellm.example:9000").expect("build");
        assert_eq!(c.base_url, "http://litellm.example:9000");
    }

    #[test] fn client_default_local_uses_known_port() {
        let c = LiteLlmClient::default_local().expect("build");
        assert_eq!(c.base_url, LiteLlmClient::DEFAULT_URL);
        // Pinned to 127.0.0.1 (not `localhost`) to dodge the IPv6
        // dual-stack flake — see DEFAULT_URL docs.
        assert_eq!(c.base_url, "http://127.0.0.1:4000");
    }

    // ---- send_chat against a fake HTTP server ----

    #[tokio::test]
    async fn send_chat_returns_assistant_content_from_mock() {
        use wiremock::{Mock, MockServer, ResponseTemplate};
        use wiremock::matchers::{method, path};

        let server = MockServer::start().await;
        let body = serde_json::json!({
            "choices": [
                {"message": {"role": "assistant", "content": "hi from mock"}}
            ]
        });
        Mock::given(method("POST"))
            .and(path("/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(200).set_body_json(body))
            .mount(&server).await;

        let client = LiteLlmClient::new(server.uri()).unwrap();
        let req    = one_turn_request("fast", "sys", "hello");
        let out    = client.send_chat(&req).await.expect("send_chat ok");
        assert_eq!(out, "hi from mock");
    }

    #[tokio::test]
    async fn send_chat_surfaces_non_2xx_as_bad_status() {
        use wiremock::{Mock, MockServer, ResponseTemplate};
        use wiremock::matchers::method;
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .respond_with(ResponseTemplate::new(500).set_body_string("upstream-down"))
            .mount(&server).await;
        let client = LiteLlmClient::new(server.uri()).unwrap();
        let req    = one_turn_request("fast", "sys", "user");
        let err    = client.send_chat(&req).await.err().expect("must error");
        match err {
            LiteLlmError::BadStatus { status, body, .. } => {
                assert_eq!(status, 500);
                assert!(body.contains("upstream-down"));
            }
            other => panic!("expected BadStatus, got {other:?}"),
        }
    }

    #[tokio::test]
    async fn send_chat_surfaces_malformed_response_as_bad_response() {
        use wiremock::{Mock, MockServer, ResponseTemplate};
        use wiremock::matchers::method;
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .respond_with(ResponseTemplate::new(200).set_body_string("{not json"))
            .mount(&server).await;
        let client = LiteLlmClient::new(server.uri()).unwrap();
        let req    = one_turn_request("fast", "sys", "user");
        let err    = client.send_chat(&req).await.err().expect("must error");
        assert!(matches!(err, LiteLlmError::BadResponse { .. }),
            "expected BadResponse; got {err:?}");
    }

    #[tokio::test]
    async fn send_chat_errors_on_empty_choices() {
        use wiremock::{Mock, MockServer, ResponseTemplate};
        use wiremock::matchers::method;
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .respond_with(ResponseTemplate::new(200).set_body_json(serde_json::json!({
                "choices": []
            })))
            .mount(&server).await;
        let client = LiteLlmClient::new(server.uri()).unwrap();
        let req    = one_turn_request("fast", "sys", "user");
        let err    = client.send_chat(&req).await.err().expect("must error");
        assert!(matches!(err, LiteLlmError::EmptyChoices),
            "expected EmptyChoices; got {err:?}");
    }

    #[tokio::test]
    async fn send_chat_errors_on_unreachable_server() {
        // Port 0 is invalid for connecting; reqwest will surface a
        // transport error. Pin the variant so callers can rely on
        // it for `aislang chat` UX ("LiteLLM appears to be down").
        let client = LiteLlmClient::new("http://127.0.0.1:1").unwrap();
        let req    = one_turn_request("fast", "sys", "user");
        let err    = client.send_chat(&req).await.err().expect("must error");
        assert!(matches!(err, LiteLlmError::Transport { .. }),
            "expected Transport; got {err:?}");
    }

    // ----------------------------------------------------------------
    // Thursday: tool wire types + send_chat_full + tool_calls round-trip
    // ----------------------------------------------------------------

    #[test] fn tool_kind_is_function_for_v01() {
        let t = Tool {
            kind: "function".into(),
            function: ToolFunction {
                name: "list_dir".into(),
                description: "List directory contents".into(),
                parameters: serde_json::json!({
                    "type": "object",
                    "properties": {"path": {"type": "string"}},
                    "required": ["path"],
                }),
            },
        };
        let s = serde_json::to_string(&t).unwrap();
        // OpenAI wire shape: `type` is the discriminator (renamed via
        // serde, not the Rust field name).
        assert!(s.contains("\"type\":\"function\""), "got: {s}");
        assert!(s.contains("\"name\":\"list_dir\""));
        assert!(s.contains("\"required\":[\"path\"]"));
    }

    #[test] fn tool_call_round_trips_with_string_arguments() {
        // OpenAI quirk: function.arguments is a JSON-encoded STRING,
        // not a JSON object. Round-trip pins this so a future
        // "helpful" refactor to JsonValue would break the wire shape
        // loudly.
        let call = ToolCall {
            id: "call_abc".into(),
            kind: "function".into(),
            function: FunctionCall {
                name: "list_dir".into(),
                arguments: r#"{"path":"/data"}"#.into(),
            },
        };
        let s = serde_json::to_string(&call).unwrap();
        // Argument string must be JSON-escaped, NOT inlined as an obj.
        assert!(s.contains(r#""arguments":"{\"path\":\"/data\"}""#),
            "arguments must be a string in the wire format; got: {s}");
        let back: ToolCall = serde_json::from_str(&s).unwrap();
        assert_eq!(back.function.arguments, r#"{"path":"/data"}"#);
    }

    #[test] fn assistant_message_with_tool_calls_omits_content() {
        // The wire shape for a "model wants to invoke tools" message:
        // role=assistant, no content, tool_calls populated.
        let m = ChatMessage {
            role: Role::Assistant,
            content: None,
            tool_calls: Some(vec![ToolCall {
                id: "call_1".into(),
                kind: "function".into(),
                function: FunctionCall {
                    name: "list_dir".into(),
                    arguments: r#"{"path":"/"}"#.into(),
                },
            }]),
            tool_call_id: None,
        };
        let s = serde_json::to_string(&m).unwrap();
        assert!(s.contains("\"role\":\"assistant\""));
        assert!(!s.contains("\"content\""),
            "content field must be omitted when None; got: {s}");
        assert!(s.contains("\"tool_calls\":"),
            "tool_calls must appear; got: {s}");
    }

    #[test] fn chat_response_parses_assistant_with_tool_calls() {
        // What LiteLLM returns when the model decides to invoke tools.
        let body = r#"{
            "choices": [{
                "message": {
                    "role": "assistant",
                    "tool_calls": [{
                        "id": "call_xyz",
                        "type": "function",
                        "function": {
                            "name": "list_dir",
                            "arguments": "{\"path\":\"/data\"}"
                        }
                    }]
                },
                "finish_reason": "tool_calls"
            }]
        }"#;
        let parsed: ChatResponse = serde_json::from_str(body).unwrap();
        let msg = &parsed.choices[0].message;
        assert_eq!(msg.role, Role::Assistant);
        assert!(msg.content.is_none(),
            "assistant invoking tools has no textual content; got {:?}",
            msg.content);
        let calls = msg.tool_calls.as_ref().expect("tool_calls present");
        assert_eq!(calls.len(), 1);
        assert_eq!(calls[0].id, "call_xyz");
        assert_eq!(calls[0].function.name, "list_dir");
        assert_eq!(calls[0].function.arguments, r#"{"path":"/data"}"#);
    }

    #[test] fn chat_request_with_tools_serializes_tools_array() {
        let mut req = one_turn_request("fast", "sys", "user");
        req.tools = Some(vec![Tool {
            kind: "function".into(),
            function: ToolFunction {
                name: "list_dir".into(),
                description: "List files".into(),
                parameters: serde_json::json!({"type": "object"}),
            },
        }]);
        let s = serde_json::to_string(&req).unwrap();
        assert!(s.contains("\"tools\":["),
            "tools array must appear; got: {s}");
        assert!(s.contains("\"name\":\"list_dir\""));
    }

    #[test] fn chat_request_omits_tools_when_none() {
        let req = one_turn_request("fast", "sys", "user");
        let s = serde_json::to_string(&req).unwrap();
        assert!(!s.contains("\"tools\""),
            "tools must be omitted on plain requests; got: {s}");
    }

    #[tokio::test]
    async fn send_chat_full_returns_tool_calls() {
        // Wiremock returns a response with tool_calls; send_chat_full
        // must propagate them through to the caller (the tool-use
        // loop in session.rs will react to them).
        use wiremock::{Mock, MockServer, ResponseTemplate};
        use wiremock::matchers::{method, path};

        let server = MockServer::start().await;
        let body = serde_json::json!({
            "choices": [{
                "message": {
                    "role": "assistant",
                    "tool_calls": [{
                        "id": "call_xyz",
                        "type": "function",
                        "function": {
                            "name": "docs__list_dir",
                            "arguments": "{\"path\":\"/data\"}"
                        }
                    }]
                }
            }]
        });
        Mock::given(method("POST"))
            .and(path("/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(200).set_body_json(body))
            .mount(&server).await;

        let client = LiteLlmClient::new(server.uri()).unwrap();
        let req    = one_turn_request("fast", "sys", "use a tool please");
        let resp   = client.send_chat_full(&req).await.expect("send_chat_full ok");
        let msg    = &resp.choices[0].message;
        let calls  = msg.tool_calls.as_ref().expect("tool_calls present");
        assert_eq!(calls[0].function.name, "docs__list_dir");
    }
}
